    lines = s.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    e = list(map(int, lines[2].split()))

    initial_gcd = a[0]
    for x in a[1:]:
        initial_gcd = gcd(initial_gcd, x)

    if initial_gcd == 1:
        return "0"

    infeasible = True
    inf_map = {}

    for i in range(n):
        a_i, e_i = a[i], e[i]

        d_list = []
        for f in range(1, int(a_i**0.5) + 1):
            if a_i % f == 0:
                if f <= k:
                    d_list.append(f)
                d = a_i // f
                if d != f and d <= k:
                    d_list.append(d)

        for d in d_list:
            new_gcd = initial_gcd // gcd(initial_gcd, d)
            if new_gcd == 1:
                inf_map[initial_gcd] = min(inf_map.get(initial_gcd, float('inf')), e_i)
                infeasible = False
                break

    if infeasible:
        return "-1"

    total_cost = 0
    new_gcd = initial_gcd
    used = 0

    while new_gcd != 1:
        best_e = float('inf')
        found = False
        for x in range(2, new_gcd + 1):
            if new_gcd % x == 0:
                if x <= k:
                    other = new_gcd // x
                    g = gcd(new_gcd, x)
                    new_val = new_gcd // g
                    if new_val == 1:
                        found = True
                        best_e = min(best_e, e[0 if new_gcd == initial_gcd else 1])
                        break
        if found:
            total_cost += best_e
            used += 1
            new_gcd = 1
        else:
            break

    if new_gcd != 1:
        return "-1"

    result = used * sum(e[used-1] for used in [1])
    return str(result)
