    def is_gp(seq):
        m = len(seq)
        # A sequence with 0 or 1 element is always a GP
        if m <= 1:
            return True

        # All zeros case is a valid GP
        if all(x == 0 for x in seq):
            return True

        # If first element is zero but sequence isn't all zeros, not a GP
        # (All terms would have to be zero if c=0 in a_n = c*b^(n-1))
        if seq[0] == 0:
            return False

        a0 = seq[0]
        a1 = seq[1]

        # Check GP property: seq[i] * seq[0] == seq[i-1] * seq[1] for all i >= 2
        # This avoids floating point division issues
        for i in range(2, m):
            if seq[i] * a0 != seq[i-1] * a1:
                return False

        return True

    # Case 0: Sequence is already a GP
    if is_gp(a):
        return '0\n'

    # Try removing each single element to see if it becomes a GP
    for i in range(n):
        if i == 0:
            rem = a[1:]
        elif i == n - 1:
            rem = a[:-1]
        else:
            rem = a[:i] + a[i+1:]

        if is_gp(rem):
            return '1\n'

    # Not possible to make GP by deleting one element
    return '2\n'
