def bfs_path(s, t, used_edges, forward, backward, exclude_vertices):
    """Find a simple path from s to t avoiding used edges and excluded vertices"""
    from collections import deque

    if s == t:
        return [s, t]

    visited = {s}
    q = deque([(s, [s])])

    while q:
        node, path = q.popleft()

        for neighbor in forward.get(node, []) + backward.get(node, []):
            if neighbor == s or neighbor in exclude_vertices:
                continue
            if neighbor in visited:
