            if forward.get(node, []) and forward.get(neighbor, []):
                if neighbor in forward.get(s, []) or neighbor in exclude_vertices:
                    continue

            new_visited = visited | {neighbor}
            new_path = path + [neighbor]

            if neighbor == t:
