def bfs_find_path(start, target, adj, forbidden, used_edges):
    """Find a simple path from start to target, avoiding forbidden nodes and edges."""
    visited = {start}
    queue = deque([(start, [start])])

    while queue:
        node, path = queue.popleft()

        if node == target:
