def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1
    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1
        grid = []
        for i in range(n):
            grid.append(list(lines[idx + i]))
        idx += n

        count = 0

        for r in range(n):
            for c in range(m):
                max_k = min(n - r, m - c)
                for k in range(2, max_k + 1):
                    valid = True

                    # Check if all border cells are '1'
                    # Top and bottom edges (including corners)
                    top_ok = all(grid[r][c + i] == '1' for i in range(k))
                    bottom_ok = all(grid[r + k - 1][c + i] == '1' for i in range(k))

                    if not top_ok or not bottom_ok:
                        continue

                    # Left and right edges (excluding corners - already checked)
                    left_ok = all(grid[r + i][c] == '1' for i in range(1, k - 1))
                    right_ok = all(grid[r + i][c + k - 1] == '1' for i in range(1, k - 1))

                    if not left_ok or not right_ok:
                        continue

                    # Check that no 1s touch the square from outside
                    # For each corner, we check its 8 neighbors
                    corners = [(r, c), (r + k - 1, c), (r, c + k - 1), (r + k - 1, c + k - 1)]

                    for (pr, pc) in corners:
                        for dr in range(-1, 2):
                            for dc in range(-1, 2):
                                nr, nc = pr + dr, pc + dc
                                if not (0 <= nr < n and 0 <= nc < m):
                                    continue
                                # Skip if this cell is inside or on the square
                                if r <= nr < r + k and c <= nc < c + k:
                                    continue
                                # If it's a '1' and outside, then we have touching foreign 1s
                                if grid[nr][nc] == '1':
                                    valid = False
                                    break
                            if not valid:
                                break
                        if not valid:
                            break

                    if not valid:
                        continue

                    # Valid axis-aligned square
                    count += 1

        for r in range(n):
            for c in range(m):
                max_k = min(n - r, m - c)
                for k in range(2, max_k + 1):
                    valid = True

                    # Check if all border cells are '1'
                    corners = [(r, c), (r + k - 1, c), (r, c + k - 1), (r + k - 1, c + k - 1)]

                    for (pr, pc) in corners:
                        if not (0 <= pr < n and 0 <= pc < m):
                            valid = False
                            break
                        if grid[pr][pc] != '1':
                            valid = False
                            break
                    if not valid:
                        continue

                    # For diagonal square, check all edge cells
                    # Top-left to top-right (diagonal going down-right)
                    for i in range(k):
                        if grid[r + i][c + i] != '1':
                            valid = False
                            break
                    if not valid:
                        continue

                    # Left diagonal: top-right to bottom-right
                    for i in range(k - 1):
                        if grid[r + i + 1][c + k - 1 - i] != '1':
                            valid = False
                            break
                    if not valid:
                        continue

                    # Right diagonal: bottom-right to bottom-left
                    for i in range(k - 1):
                        if grid[r + k - 1 - i][c + i] != '1':
                            valid = False
                            break
                    if not valid:
                        continue

                    # Bottom-left to top-left (diagonal going up-right)
                    for i in range(k):
                        if grid[r + k - 1 - i][c + k - 1 - i] != '1':
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check that no 1s touch the square from outside
                    border_cells = set()
                    for i in range(k):
                        border_cells.add((r + i, c + i))
                    for i in range(k - 1):
                        border_cells.add((r + i + 1, c + k - 1 - i))
                    for i in range(k - 1):
                        border_cells.add((r + k - 1 - i, c + i))
                    for i in range(k):
                        border_cells.add((r + k - 1 - i, c + k - 1 - i))

                    for (pr, pc) in border_cells:
                        for dr in range(-1, 2):
                            for dc in range(-1, 2):
                                nr, nc = pr + dr, pc + dc
                                if not (0 <= nr < n and 0 <= nc < m):
                                    continue
                                if (nr, nc) in border_cells:
                                    continue
                                if grid[nr][nc] == '1':
                                    valid = False
                                    break
                            if not valid:
                                break
                        if not valid:
                            break

                    if not valid:
                        continue

                    # Valid diagonal square
                    count += 1

        results.append(str(count))

    return '\n'.join(results)
