    """
    Count the number of different ways to decompose n into distinct Fibonacci numbers.

    The Fibonacci sequence here is: F1=1, F2=2, F3=3, F4=5, F5=8, ...
    This is slightly different from the standard Fibonacci starting with 0,1.
    """
    if n <= 0:
        return 0

    # Generate Fibonacci numbers up to n
    fibs = [1, 2]
    while fibs[-1] + fibs[-2] < n:
        fibs.append(fibs[-1] + fibs[-2])

    # Convert n to its Zeckendorf representation
    # Zeckendorf: every positive integer can be uniquely represented as sum 
    # of non-consecutive Fibonacci numbers

    # Calculate the Zeckendorf representation indices
    zeck_indices = []
    idx = len(fibs) - 1
    temp = n

    while idx >= 0 and temp > 0:
        if fibs[idx] <= temp:
            zeck_indices.append(idx)
            temp -= fibs[idx]
        idx -= 1

    if temp > 0:
        return 0  # Should not happen for valid Fibonacci numbers

    # The number of decompositions is related to the number of "gaps" in Zeckendorf representation
    # Each gap of size >= 1 contributes additional decomposition possibilities

    count = 1
    last_idx = len(fibs)

    # Process zeck_indices from left to right
    for i, z_idx in enumerate(zeck_indices):
        # Check the gap before this Fibonacci number
        if i > 0:
            gap = z_idx - zeck_indices[i-1] - 1
            # Each gap >= 1 contributes (gap) additional possibilities
            count += (gap)
        else:
