Looking at this problem, I need to find a Nonogram profile from its mask. The mask shows cells that are filled in EVERY valid solution. So:
- '#' positions must be filled in every valid placement
- '_' positions must be empty in every valid placement

The key insight is that I can extract the profile from consecutive runs of '#' in the mask, then verify if all valid placements of this profile fill exactly the '#' positions (and no '_' positions).

```python
def solution(m: str) -> str:
    n = len(m)

    # Handle empty string
    if n == 0:
        return "0\n\n"

    # Check if mask has any filled cells
    if m.count('#') == 0:
        return "0\n\n"

    # Extract profile from consecutive runs of '#'
    profile = []
    current_run = 0
    for c in m:
        if c == '#':
            current_run += 1
        else:
            if current_run > 0:
                profile.append(current_run)
                current_run = 0
    if current_run > 0:
        profile.append(current_run)

    if len(profile) == 0:
        return "0\n\n"

    # Get the set of positions that must be filled (marked '#' in mask)
    mask_filled = set(i for i, c in enumerate(m) if c == '#')

    # Generate all valid placements and check if they all produce the same filled set
    total_length = sum(profile)
    num_blocks = len(profile)
    min_space = total_length + num_blocks - 1  # length + (num_blocks-1) gaps

    if min_space > n:
        return "-1\n"

    # Check all valid placements
    import itertools

    for start in range(n - min_space + 1):
        filled = set()
        pos = start
        valid_placement = True

        for i, length in enumerate(profile):
            # Check if any position in this block is marked '_'
            for j in range(pos, pos + length):
                if m[j] == '_':
                    valid_placement = False
                    break
            if not valid_placement:
                break

            # Add this block's positions
            filled.update(range(pos, pos + length))

            if i < num_blocks - 1:
                pos += length + 1  # 1 cell gap between blocks
            else:
                pos += length

        if not valid_placement:
            continue

        # If a valid placement exists, check if it matches the mask
        if filled != mask_filled:
            return "-1\n"

    return f"{len(profile)}\n{' '.join(map(str, profile))}\n"


def main():
    # Test cases
    test_cases = [
        "___\n",
        "_#\n",
        "__#_____\n",
    ]

    for tc in test_cases:
        result = solution(tc.strip())
        print(f"Input: {tc.strip()!r}")
        print(f"Output: {result!r}")
        print()
