        bad_intervals = []
        i = 0
        while i < n:
            remainder = arr[i] % g
            if remainder == 0:
                # Already divisible - good
                i += 1
            elif remainder == 1 or remainder >= g - 1:
                # Can be changed to be divisible (cost b) - good
                i += 1
            else:
                # Bad element - find the consecutive bad interval
                j = i
                while j < n:
                    rem = arr[j] % g
                    if rem == 0 or rem == 1 or rem >= g - 1:
                        break
                    j += 1
                bad_intervals.append((i, j - 1))
                i = j

        # Calculate cost with and without removing any segment
        cost_with_fixes = 0
        for i in range(n):
