                        if rem == 1 or rem >= g - 1:
                            rem_cost += b

                current_cost = len_seg * a + rem_cost

                # Also try fixing the removed segment too (for comparison)
                fix_cost = len_seg * b + rem_cost
                current_cost = min(current_cost, fix_cost)

                if current_cost < min_total:
                    min_total = current_cost

        # Handle case where we don't remove any segment from the identified bad intervals
        # but may still need to remove other segments optimally
        # Actually, we need to ensure at least one element remains and it works

        # Try removing each prefix that has a good element
        for i in range(n):
            count_good_before = sum(1 for k in range(i) if arr[k] % g in [0, 1, g-1])
            count_bad_before = i - count_good_before

            if count_good_before > 0:
                # We can remove the first bad segment before good element at i
                prev_good = -1
                bad_pos = -1
                can_del = True
                needed_to_remove = 0

                for k in range(i):
                    if arr[k] % g in [0, 1, g-1]:
