                            needed_to_remove += bad_pos - prev_good if bad_pos else 1
                        prev_good = k
                    else:
                        if bad_pos < 0:
                            bad_pos = prev_good + 1

    # Alternative approach - simpler greedy
    min_cost = float('inf')

    for first in range(n):
        base_val = arr[first]

        for offset in [-1, 0, 1]:
            g = base_val + offset
            if g <= 1:
                continue

            cost = 0

            # Calculate minimum cost for this g
            total_bad_count = 0
            bad_elements = []

            for idx in range(n):
                rem = arr[idx] % g
                if rem == 0 or rem == 1 or rem >= g - 1:
                    continue
                else:
                    bad_elements.append((idx, arr[idx]))
                    total_bad_count += 1

            if total_bad_count == 0:
                min_cost = min(min_cost, cost)
                continue

            # Try removing consecutive segments
            merge_bad = []
            i = 0
            while i < len(bad_elements):
                j = i
                while j + 1 < len(bad_elements) and bad_elements[j][0] + 1 == bad_elements[j + 1][0]:
                    j += 1
                merge_bad.append((bad_elements[i][0], bad_elements[j][1]))
                i = j + 1

            for seg in merge_bad:
                seg_len = seg[1] - seg[0] + 1
                remaining = n - seg_len
                if remaining < 1:
                    continue

                cost = seg_len * a
                for idx, _ in bad_elements:
                    if not (seg[0] <= idx <= seg[1]):
                        cost += b

                min_cost = min(min_cost, cost)

    return str(int(min_cost)) if min_cost != float('inf') else "0"
