Looking at this problem, I need to construct two strings s1 and s2 of lengths n and m such that when they're used in a Fibonacci-like recurrence (sk = s_{k-2} + s_{k-1}), the resulting sk has exactly x occurrences of "AC".

The key insight is that for k=3, sk is simply s1+s2, so we only need to count:
1. AC occurrences within s1
2. AC occurrences within s2
3. One AC if s1 ends with 'A' and s2 starts with 'C'

For larger k, the strings grow exponentially. However, we can try various simple patterns and check which ones work.

```python
def solution(input_str):
    k, x, n, m = map(int, input_str.split())

    def count_ac(s):
        return sum(1 for i in range(len(s) - 1) if s[i] == 'A' and s[i+1] == 'C')

    def compute_sk(s1, s2, k):
        if k == 1:
            return s1
        if k == 2:
            return s2
        sequences = [s1, s2]
        for i in range(3, k + 1):
            sequences.append(sequences[i-2] + sequences[i-1])
        return sequences[-1]

    def check(s1, s2, k):
        return count_ac(compute_sk(s1, s2, k))

    # Try many simple patterns
    if k == 3:
        # Direct case: sk = s1 + s2
        for i1 in range(n):
            for i2 in range(m):
                # s1 ends with char at i1, s2 starts with char at i2
                s1 = ['B'] * n
                s2 = ['B'] * m

                # Try making AC at boundary
                s1[i1] = 'A' if i1 < n-1 else 'A'
                s2[i2] = 'C' if i2 > 0 else 'C'

                if i1 < n and s1[i1] == 'A':
                    s1[n-1] = 'B' if n-1 != i1 else 'B'
                if i2 < m and s2[i2] == 'C':
                    s2[0] = 'B' if m-1 != i2 else 'B'

                s1 = ''.join(s1)
                s2 = ''.join(s2)
                if check(s1, s2, k) == x:
                    return s1 + '\n' + s2

    # Systematic search with patterns
    # Pattern 1: All A's and C's at strategic positions
    for a1 in range(n + 1):
        for a2 in range(m + 1):
            # s1 starts with A's
            s1 = 'A' * a1 + 'B' * (n - a1)
            # s2 ends with C's  
            s2 = 'B' * (m - a2) + 'C' * a2

            if count_ac(compute_sk(s1, s2, k)) == x:
                return s1 + '\n' + s2

            # Pattern 2: AC at beginning
            if n >= 2:
                s1 = 'A' + 'B' * (n - 2) + 'C'
                s2 = 'B' * m
                if count_ac(compute_sk(s1, s2, k)) == x:
                    return s1 + '\n' + s2

            # Pattern 3: AC at end
            if n >= 2:
                s1 = 'B' * (n - 2) + 'A' + 'C'
                s2 = 'B' * m
                if count_ac(compute_sk(s1, s2, k)) == x:
                    return s1 + '\n' + s2

    # Try all C as AC
    for c1 in range(n):
        for c2 in range(m):
            # s1 has AC at position c1, s2 has AC at position c2
            if n >= 2 and m >= 2:
                s1 = 'B' * c1 + 'A' + 'C' + 'B' * (n - 2 - c1)
                s2 = 'B' * c2 + 'A' + 'C' + 'B' * (m - 2 - c2)
                if count_ac(compute_sk(s1, s2, k)) == x:
                    return s1 + '\n' + s2

    return 'Happy new year!\n'


