        else:
            a, b = abs(lits[0]), abs(lits[1])
            adj[a].append(b)
            adj[b].append(a)

    visited = [False] * (m + 1)
    ans = 1

    def get_component(start):
        comp = []
        stack = [start]
        visited[start] = True
        while stack:
            u = stack.pop()
            comp.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    stack.append(v)
        return comp

    for i in range(1, m + 1):
        if not visited[i]:
            comp = get_component(i)

            # Get initially fixed variables from unit constraints
            initially_fixed = {}
            for v in comp:
                if v in unit_val:
                    initially_fixed[v] = unit_val[v]

            # Propagate constraints
            changed = True
            while changed:
                changed = False
                for u in comp:
                    if u in initially_fixed:
                        val = initially_fixed[u]
                        for v in adj[u]:
                            if v not in initially_fixed:
                                if val == False:  # Clause (x_u OR x_v), if u is False, v must be True
                                    initially_fixed[v] = True
                                    changed = True

                # Check contradictions
                violated = False
                for u in comp:
                    for v in adj[u]:
                        if u in initially_fixed and v in initially_fixed:
                            if initially_fixed[u] == False and initially_fixed[v] == False:
                                violated = True
                                break
                        if violated:
                            break
                    if violated:
                        break

                if violated:
                    ans = 0
                    break

            if ans == 0:
                continue

            # Count fixed vs free
            fixed_count = len(initially_fixed)
            free_count = len(comp) - fixed_count
            ans = (ans * pow(2, free_count, MOD)) % MOD

    # Never-appearing variables have 2 choices each
    never_count = m - len(appearing_vars)
    ans = (ans * pow(2, never_count, MOD)) % MOD

    return f"{ans}\n"
